import { expect, test } from "bun:test";
import { readdirSync, readFileSync } from "node:fs";
import { app } from "../src/app";

// architecture/excalidraw.json is generated by `make diagram`. These fail when it falls behind the code.
const root = new URL("../../", import.meta.url);
const texts: string[] = JSON.parse(readFileSync(new URL("architecture/excalidraw.json", root), "utf8"))
  .elements.map((e: { text?: string }) => e.text ?? "");
const drawn = new Set(texts);

test("every route is drawn", () => {
  const rows = texts.flatMap((t) => [...t.matchAll(/^(GET|POST|PUT|PATCH|DELETE) +(\S+)/gm)].map((m) => `${m[1]} ${m[2]}`));
  const routes = [...new Set(app.routes.map((r) => `${r.method} ${r.path}`))];
  expect(rows.sort()).toEqual(routes.sort());
});

test("every table is drawn", () => {
  const schema = readFileSync(new URL("migrations/schema.sql", root), "utf8");
  const missing = [...schema.matchAll(/CREATE TABLE (\w+)/g)].map((m) => m[1]).filter((t) => !drawn.has(t));
  expect(missing).toEqual([]);
});

test("every service is drawn", () => {
  const services = readdirSync(new URL("server/src/services", root)).map((f) => `services/${f}`);
  const missing = [...services, "server/src/server.ts", "server/src/worker.ts", "install/index.ts"].filter((s) => !drawn.has(s));
  expect(missing).toEqual([]);
});
